export function getGenesisProgramProgramErrorFromCode(
  code: GenesisProgramProgramErrorCode,
  cause?: Error
): GenesisProgramProgramError {
  if (__DEV__) {
    return new GenesisProgramProgramError(
      code,
      ...(
        genesisProgramProgramErrorCodeMap as Record<
          GenesisProgramProgramErrorCode,
          [string, string]
        >
      )[code],
      cause
    );
  }

  return new GenesisProgramProgramError(
    code,
    'Unknown',
    'Error message not available in production bundles. Compile with __DEV__ set to true to see more information.',
    cause
  );
}
